/**
 * Client brand logos, inlined as monochrome SVGs.
 *
 * Each logo is drawn with `fill="currentColor"` so it inherits the text color
 * of its slot (e.g. `text-muted-foreground`) and flips correctly in dark mode.
 * We do NOT ship the brands' native colors — monochrome keeps the work cards
 * looking like one designed system rather than a scrapbook of clashing marks.
 *
 * Source SVGs: Onfly (official site), Whirlpool + Santander (worldvectorlogo),
 * recolored to a single fill. Each keeps its original viewBox so aspect ratio
 * is preserved; the render slot fixes the height and lets width flow.
 */
import { useLayoutEffect, useRef, useState, type SVGProps } from "react"

