/**
 * Esfera — Santander's loyalty program, the actual product Marcel built the
 * design system for. The official asset is a colored raster JPEG that can't
 * tint, so this is a monochrome recreation: "Esfera" and "Santander" side by
 * side at the same size, separated by a dot, with the Santander flame between
 * them. Wordmarks use the site font (Geist) so the whole mark inherits
 * `currentColor` like the other logos; the flame is the vector path lifted from
 * the Santander logo.
 */
/**
 * Layout constants for the Esfera lockup, in the SVG's own units (font-size 44).
 * Gaps are the empty space around the dot and flame; the flame is drawn at a
 * fixed scale. Everything else is measured from the real rendered text so the
 * pieces never overlap or clip regardless of the font's actual metrics.
 */
const ESFERA_FONT = "'Geist Variable', sans-serif"
const ESFERA_SIZE = 44
const GAP = 16 // space on each side of the dot / flame
const DOT_R = 3.5
const FLAME_SCALE = 0.82 // flame native height ~41 → ~34, matching the cap height
const FLAME_W = 52 * FLAME_SCALE // native flame width ~52
const FALLBACK_ESFERA_W = 150 // used before measurement / on SSR
const FALLBACK_SANT_W = 232
const USCORE_W = 20 // the "_" accent after Esfera
const USCORE_GAP = 4 // small space between "Esfera" and its underscore

export function EsferaLogo(props: SVGProps<SVGSVGElement>) {
  const esferaRef = useRef<SVGTextElement>(null)
  const santRef = useRef<SVGTextElement>(null)
  const [esferaW, setEsferaW] = useState(FALLBACK_ESFERA_W)
  const [santW, setSantW] = useState(FALLBACK_SANT_W)

  // Measure the real rendered width of each wordmark so the dot, flame, and
  // second word are placed in flow — no guessing, nothing clips.
  useLayoutEffect(() => {
    if (esferaRef.current) setEsferaW(esferaRef.current.getComputedTextLength())
    if (santRef.current) setSantW(santRef.current.getComputedTextLength())
  }, [])

  // x-positions derived from the measured widths.
  // The "_" accent sits right after "Esfera"; the dot separates the two brands;
  // the flame hugs "Santander" (small gap) since they read as one lockup.
  const uscoreX = esferaW + USCORE_GAP
  const dotX = uscoreX + USCORE_W + GAP + DOT_R
  const flameX = dotX + DOT_R + GAP
  const santX = flameX + FLAME_W + 6 // flame hugs the wordmark
  const totalW = santX + santW

  return (
    <svg
      viewBox={`0 0 ${totalW} 56`}
      fill="currentColor"
      role="img"
      aria-label="Esfera · Santander"
      {...props}
    >
      <text
        ref={esferaRef}
        x="0"
        y="42"
        fontFamily={ESFERA_FONT}
        fontSize={ESFERA_SIZE}
        fontWeight="600"
        letterSpacing="-1"
      >
        Esfera
      </text>

      {/* Underscore accent, sitting on the baseline right after "Esfera" */}
      <rect x={uscoreX} y="38" width={USCORE_W} height="5" rx="1" />

      {/* Dot separator, centered on the cap height */}
      <circle cx={dotX} cy="26" r={DOT_R} />

      {/* Santander flame (native bounds ~52×41) */}
      <g transform={`translate(${flameX} 10) scale(${FLAME_SCALE})`}>
        <path d="m31.5 19.5c-.1-1.5-.5-3-1.3-4.3l-6.8-11.9c-.5-.9-.9-1.9-1.1-2.9l-.3.5c-1.7 2.9-1.7 6.6 0 9.5l5.5 9.5c1.7 2.9 1.7 6.6 0 9.5l-.3.5c-.2-1-.6-2-1.1-2.9l-5-8.7-3.2-5.6c-.5-.9-.9-1.9-1.1-2.9l-.3.5c-1.7 2.9-1.7 6.5 0 9.5l5.5 9.5c1.7 2.9 1.7 6.6 0 9.5l-.3.5c-.2-1-.6-2-1.1-2.9l-6.9-11.9c-.9-1.6-1.3-3.4-1.3-5.2-7.3 1.9-12.4 6-12.4 10.7 0 6.6 9.8 11.9 21.9 11.9s21.9-5.3 21.9-11.9c.1-4.5-4.9-8.6-12.3-10.5z" />
      </g>

      <text
        ref={santRef}
        x={santX}
        y="42"
        fontFamily={ESFERA_FONT}
        fontSize={ESFERA_SIZE}
        fontWeight="600"
        letterSpacing="-1"
      >
        Santander
      </text>
    </svg>
  )
}
